import type { ComponentProps } from 'react';

export type RoxyUpagrahaTableProps = ComponentProps<typeof Element>;

export function RoxyUpagrahaTable(props: RoxyUpagrahaTableProps) {
	return <Element {...props} />;
}

export default RoxyUpagrahaTable;
